before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
#include <vector>
int main() {
    std::vector<int> values{2, 4, 6};
    auto position = values.begin();
    position = values.erase(position);
    if (position != values.end()) std::cout << *position << '\n';
    else std::cout << "end\n";
}

```

